eadcrumb i{display:none}.content-wrap{padding:16px}.topbar{padding:0 14px}}
.app-version{font-size:11px;font-weight:600;letter-spacing:.04em;color:#50708d;background:#eef4f8;border:1px solid #d8e4ec;padding:4px 8px;border-radius:12px}
</style>

